function solve(board, words) {
  const rows = board.length;
  const unique = [];
  const seen = new Set();
  for (const w of words) {
    if (w !== '' && !seen.has(w)) { seen.add(w); unique.push(w); }
  }
  function dfs(r, c, word, k, visited) {
    if (r < 0 || r >= rows || c < 0 || c >= board[r].length) return false;
    if (board[r][c] !== word[k]) return false;
    const key = r + ',' + c;
    if (visited.has(key)) return false;
    if (k === word.length - 1) return true;
    visited.add(key);
    const found =
      dfs(r + 1, c, word, k + 1, visited) ||
      dfs(r - 1, c, word, k + 1, visited) ||
      dfs(r, c + 1, word, k + 1, visited) ||
      dfs(r, c - 1, word, k + 1, visited);
    visited.delete(key);
    return found;
  }
  const found = [];
  for (const w of unique) {
    let ok = false;
    for (let r = 0; r < rows && !ok; r++) {
      for (let c = 0; c < board[r].length && !ok; c++) {
        if (board[r][c] === w[0] && dfs(r, c, w, 0, new Set())) ok = true;
      }
    }
    if (ok) found.push(w);
  }
  found.sort();
  return found;
}

function solve(board, words) {
  const rows = board.length;
  const root = {};
  for (const w of words) {
    if (w === '') continue;
    let node = root;
    for (const ch of w) {
      if (!node[ch]) node[ch] = {};
      node = node[ch];
    }
    node['$'] = w;
  }
  const found = [];
  const visited = new Set();
  function dfs(r, c, node) {
    if (r < 0 || r >= rows || c < 0 || c >= board[r].length) return;
    const key = r + ',' + c;
    if (visited.has(key)) return;
    const nxt = node[board[r][c]];
    if (!nxt) return;
    if (nxt['$'] !== undefined) {
      found.push(nxt['$']);
      nxt['$'] = undefined;
    }
    visited.add(key);
    dfs(r + 1, c, nxt);
    dfs(r - 1, c, nxt);
    dfs(r, c + 1, nxt);
    dfs(r, c - 1, nxt);
    visited.delete(key);
  }
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < board[r].length; c++) {
      dfs(r, c, root);
    }
  }
  found.sort();
  return found;
}
